import { render } from '@solidjs/web';
import {
  createSignal,
  createMemo,
  Loading,
  Errored,
  isPending,
  refresh,
} from 'solid-js';

async function fetchUser(id) {
  await new Promise((resolve) => setTimeout(resolve, 500));
  if (id === '404') throw new Error('User not found');
  return { id, name: `Explorer ${id}` };
}
function App() {
  const [userId, setUserId] = createSignal('1');
  const user = createMemo(() => ({
    id: userId(),
    name: 'Replace this with fetchUser(userId())',
  }));
  return (
    <>
      <input
        aria-label="User ID"
        value={userId()}
        onInput={(event) => setUserId(event.currentTarget.value)}
      />
      <button
        onClick={() => {
          void refresh(user);
        }}
      >
        Reload
      </button>
      <Errored
        fallback={(error, retry) => (
          <button
            onClick={() => {
              void refresh(user).then(retry, () => {});
            }}
          >
            {error().message} — retry
          </button>
        )}
      >
        <Loading fallback={<p>Loading user...</p>}>
          <span>{isPending(user) && 'Updating...'}</span>
          <pre>{JSON.stringify(user(), null, 2)}</pre>
        </Loading>
      </Errored>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

